import { test, expect } from '@playwright/test';

test.describe('Dropdown Selection', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dropdown');
  });

  test('should display disabled prompt initially', async ({ page }) => {
    const dropdown = page.locator('#dropdown');
    const selectedOption = dropdown.locator('option[selected]');

    await expect(selectedOption).toHaveText('Please select an option');
    await expect(dropdown).toHaveValue('');
  });

  test('should select Option 2 and update the dropdown value', async ({ page }) => {
    const dropdown = page.locator('#dropdown');

    await dropdown.selectOption('2');

    await expect(dropdown).toHaveValue('2');
    const selectedOption = dropdown.locator('option[selected]');
    await expect(selectedOption).toHaveText('Option 2');
  });

  test('should verify Option 2 is the selected option after selection', async ({ page }) => {
    const dropdown = page.locator('#dropdown');

    await dropdown.selectOption('Option 2');

    const option2 = page.locator('#dropdown option[value="2"]');
    await expect(option2).toHaveAttribute('selected', '');
    await expect(dropdown).toHaveValue('2');
  });
});
